"""PR-039: the two demo datasets tell the same story.

* ``frontend/src/demo/`` (static, no backend; generated by ``frontend/scripts/generate-demo.ts``)
* ``aiops demo seed`` (Postgres, real replays of the recorded fixtures; used by ``make demo``)

They keep their own layouts (docs/setup/demo.md), but every static scenario must pass the
same ground truth as the replays (``scenarios/*/expected.yaml``, the investigation evals),
and each release version the static story names must exist in that scenario's fixtures.
"""

from __future__ import annotations

import json
import re
from pathlib import Path

import pytest

from aiops.core.models import Investigation
from aiops.evals.investigation import score_investigation
from aiops.evals.scenario import Scenario, load_scenarios

ROOT = Path(__file__).resolve().parents[3]
UI_DEMO = ROOT / "frontend" / "src" / "demo"
FIXTURES = ROOT / "backend" / "tests" / "fixtures"
SCENARIOS = {s.id: s for s in load_scenarios(ROOT / "scenarios")}
VERSION = re.compile(r"\bv\d+\.\d+\.\d+\b")


def _ui(scenario_id: str) -> tuple[Investigation, list[str]]:
    payload = json.loads((UI_DEMO / f"scenario-{scenario_id}.json").read_text())
    # The static story lets a re-run step's findings cite evidence of an earlier step; the
    # backend model only accepts a result's own evidence ids (not a contract rule).
    for result in payload["investigation"]["results"]:
        own = {e["id"] for e in result["evidence"]}
        for finding in result["findings"]:
            finding["evidence_ids"] = [i for i in finding["evidence_ids"] if i in own]
    return Investigation.model_validate(payload["investigation"]), [
        e["type"] for e in payload["events"]
    ]


def test_same_scenarios_in_both_datasets() -> None:
    ui = {p.stem.removeprefix("scenario-") for p in UI_DEMO.glob("scenario-S*.json")}
    assert ui == set(SCENARIOS)


@pytest.mark.parametrize("scenario_id", sorted(SCENARIOS))
def test_static_scenario_passes_the_replay_ground_truth(scenario_id: str) -> None:
    scenario: Scenario = SCENARIOS[scenario_id]
    inv, events = _ui(scenario_id)
    assert inv.context is not None and inv.context.service == scenario.service
    failed = [c for c in score_investigation(scenario, inv, events) if not c.passed]
    assert not failed, [f"{c.name}: {c.detail}" for c in failed]


@pytest.mark.parametrize("scenario_id", sorted(s for s in SCENARIOS if s != "S0"))
def test_static_story_names_only_recorded_release_versions(scenario_id: str) -> None:
    inv, _ = _ui(scenario_id)
    assert inv.report is not None
    story = " ".join([inv.report.summary, *(h.statement for h in inv.hypotheses)])
    recorded = " ".join(p.read_text() for p in FIXTURES.glob(f"*/{scenario_id}/*.json"))
    missing = sorted(v for v in set(VERSION.findall(story)) if v not in recorded)
    assert not missing, f"{scenario_id} names versions absent from its fixtures: {missing}"
